"""Allocate private mesh identities without changing original Bundle IDs.

Existing single-region fills keep their Bundle-based key namespaces. Additional
regions receive disjoint component-local namespaces above every original Bundle
ID. Sorting original span identities makes allocation independent of table and
object order. Moving vertices changes no identity. A topology rebuild may
reallocate these private IDs; they are not persistent user feature IDs.
"""
from dataclasses import dataclass

LIMIT = 2**20


def _integer(value):
    if type(value) is not int or not 0 <= value < LIMIT:
        raise ValueError('Region namespace requires a nonnegative bounded integer')
    return value


def continuation_key(row):
    bundle = _integer(row['bundle_id'])
    spans = tuple(sorted(tuple(_integer(v) for v in span) for span in row['boundary_span_ids']))
    cross = tuple(_integer(v) for v in row['crossing_span_id'])
    if len(spans) != 2 or any(len(span) != 3 for span in spans) or len(cross) != 3:
        raise ValueError('A continuation needs two original boundary spans and one crossing span')
    if len({spans[0][0], spans[1][0], cross[0]}) != 3:
        raise ValueError('Boundary and crossing Streets must be distinct')
    return bundle, spans, cross


def internal_cycle_key(row):
    """Use original incidences, independently of traversal or private row order."""
    owners = tuple(sorted(_integer(v) for v in row['logical_junction_ids']))
    sites = tuple(sorted(_integer(v) for v in row['physical_junction_ids']))
    bundles = tuple(sorted(_integer(v) for v in row['bundle_ids']))
    if (not owners or not bundles or not 3 <= len(sites) <= 64 or
            any(len(set(v)) != len(v) for v in (owners, sites, bundles))):
        raise ValueError('Internal region needs unique original owners, sites and Bundles')
    edges, used = [], set()
    members = row['members']
    if len(members) != len(sites):
        raise ValueError('An internal region must cover one unbranched cycle')
    for member, following in zip(members, (*members[1:], members[0])):
        span = tuple(_integer(v) for v in member['span_id'])
        if len(span) != 3 or span[0] in used:
            raise ValueError('A cycle member needs a unique complete original span')
        used.add(span[0])
        ends = []
        for label, jid in (('from_end', 'from_junction'), ('to_end', 'to_junction')):
            end = member[label]
            sid, section, at = (_integer(end[key]) for key in ('street_id', 'section_id', 'end'))
            if sid != span[0] or at not in (0, 1) or section != span[1+at]:
                raise ValueError('Internal region endpoint differs from its original span')
            ends.append((at, _integer(member[jid])))
        ends.sort()
        if [e[0] for e in ends] != [0, 1] or ends[0][1] == ends[1][1]:
            raise ValueError('Internal member must connect two distinct original endpoints')
        if member['to_junction'] != following['from_junction']:
            raise ValueError('Internal member order must follow original incidence')
        edges.append((_integer(member['bundle_id']), span, tuple(ends)))
    if (tuple(sorted({edge[0] for edge in edges})) != bundles or
            tuple(sorted(member['from_junction'] for member in members)) != sites):
        raise ValueError('Internal region omitted or repeated an original Bundle or junction')
    return owners, sites, tuple(sorted(edges))


@dataclass(frozen=True)
class RegionNamespaces:
    reserved_bundle_ids: tuple[int, ...]
    continuations: tuple[tuple[tuple, int], ...]
    internal_cycles: tuple[tuple[tuple, int], ...] = ()

    @classmethod
    def allocate(cls, original_bundle_ids, primary_bundle_ids, continuation_rows, *, internal_rows=()):
        reserved = tuple(sorted(_integer(v) for v in original_bundle_ids))
        primary = tuple(_integer(v) for v in primary_bundle_ids)
        if len(set(reserved)) != len(reserved) or len(set(primary)) != len(primary):
            raise ValueError('Original and primary Bundle identities must be unique')
        if not set(primary) <= set(reserved):
            raise ValueError('Primary separator lost its original Bundle identity')
        keys = tuple(sorted(continuation_key(row) for row in continuation_rows))
        if len(keys) != len(set(keys)):
            raise ValueError('Duplicate original continuation region')
        if any(key[0] not in primary for key in keys):
            raise ValueError('A continuation requires its declared primary separator region')
        internal = tuple(sorted(internal_cycle_key(row) for row in internal_rows))
        if len(internal) != len(set(internal)):
            raise ValueError('Duplicate original internal region')
        if any(edge[0] not in reserved for key in internal for edge in key[2]):
            raise ValueError('Internal region lost an original participating Bundle')
        first = max(reserved, default=-1)+1
        if first+len(keys)+len(internal) > LIMIT:
            raise ValueError('No representable region namespaces remain')
        # Keep the established continuation allocations exactly; new internal
        # regions follow them in the same shared private key space.
        return cls(reserved, tuple((key, first+i) for i, key in enumerate(keys)),
                   tuple((key, first+len(keys)+i) for i, key in enumerate(internal)))

    def continuation(self, row):
        key = continuation_key(row)
        for candidate, region_id in self.continuations:
            if candidate == key:
                return region_id
        raise ValueError('Continuation has no allocated region namespace')

    def internal_cycle(self, row):
        key = internal_cycle_key(row)
        for candidate, region_id in self.internal_cycles:
            if candidate == key:
                return region_id
        raise ValueError('Internal cycle has no allocated region namespace')
